3	// Guard of the mise tasks of the bench (DEVDESK-504, step 8, CA1 and CA7). It
4	// reads mise.toml at the repository root and runs nothing: the six
5	// nexus-bench:* tasks must exist, call the command, stay out of every task the
6	// standard checks run (ci, check, test, test-race), and kubectl must be
7	// declared where it does not slow the CI down.
8	//
9	// go.mod carries no TOML library and none may be added for a test, so
10	// mise.toml is read by a small line-based reader that understands what the
11	// file uses: [tables] and [tasks."quoted:name"] headers, key = value, values
12	// spread over several lines (arrays, inline tables, ''' and """ strings) and
13	// comments.
14	
15	import (
16		"os"
17		"path/filepath"
18		"regexp"
19		"sort"
20		"strings"
21		"testing"
22	)
23	
24	const miseBenchPrefix = "nexus-bench"
25	
26	var miseBenchSubcommands = []string{"up", "provision", "down", "status", "render"}
27	
28	// miseFile maps a table path ("tasks|build", "tools") to its keys, each with
29	// the raw text of its value.
30	type miseFile map[string]map[string]string
31	
32	// miseRepoRoot walks up from the working directory to the folder holding go.mod.
33	func miseRepoRoot(t *testing.T) string {
34		t.Helper()
35		dir, err := os.Getwd()
36		if err != nil {
37			t.Fatal(err)
38		}
39		for {
40			if _, err := os.Stat(filepath.Join(dir, "go.mod")); err == nil {
41				return dir
42			}
43			parent := filepath.Dir(dir)
44			if parent == dir {
45				t.Fatal("go.mod not found above the working directory")
46			}
47			dir = parent
48		}
49	}
50	
51	func loadMise(t *testing.T) miseFile {
52		t.Helper()
53		data, err := os.ReadFile(filepath.Join(miseRepoRoot(t), "mise.toml"))
54		if err != nil {
55			t.Fatalf("read mise.toml: %v", err)
56		}
57		return parseMise(string(data))
58	}
59	
60	// miseStripComment removes a trailing "# ..." that is outside a string.
61	func miseStripComment(line string) string {
62		var quote byte
63		for i := 0; i < len(line); i++ {
64			c := line[i]
65			switch {
66			case quote == '"' && c == '\\':
67				i++
68			case quote != 0:
69				if c == quote {
70					quote = 0
71				}
72			case c == '"' || c == '\'':
73				quote = c
74			case c == '#':
75				return line[:i]
76			}
77		}
78		return line
79	}
80	
81	// miseDepth is how many [ and { are still open after line, outside strings.
82	func miseDepth(line string) int {
83		depth := 0
84		var quote byte
85		for i := 0; i < len(line); i++ {
86			c := line[i]
87			switch {
88			case quote == '"' && c == '\\':
89				i++
90			case quote != 0:
91				if c == quote {
92					quote = 0
93				}
94			case c == '"' || c == '\'':
95				quote = c
96			case c == '[' || c == '{':
97				depth++
98			case c == ']' || c == '}':
99				depth--
100			}
101		}
102		return depth
103	}
104	
105	// miseHeader splits "[tasks.\"nexus-bench:up\".tools]" into its parts.
106	func miseHeader(line string) []string {
107		inner := strings.TrimSpace(strings.TrimSuffix(strings.TrimPrefix(line, "["), "]"))
108		var parts []string
109		var cur strings.Builder
110		var quote byte
111		for i := 0; i < len(inner); i++ {
112			c := inner[i]
113			switch {
114			case quote != 0:
115				if c == quote {
116					quote = 0
117				} else {
118					cur.WriteByte(c)
119				}
120			case c == '"' || c == '\'':
121				quote = c
122			case c == '.':
123				parts = append(parts, strings.TrimSpace(cur.String()))
124				cur.Reset()
125			default:
126				cur.WriteByte(c)
127			}
128		}
129		return append(parts, strings.TrimSpace(cur.String()))
130	}
131	
132	func parseMise(text string) miseFile {
133		file := miseFile{}
134		section := ""
135		lines := strings.Split(text, "\n")
136		for i := 0; i < len(lines); i++ {
137			trimmed := strings.TrimSpace(lines[i])
138			if trimmed == "" || strings.HasPrefix(trimmed, "#") {
139				continue
140			}
141			if strings.HasPrefix(trimmed, "[") && !strings.HasPrefix(trimmed, "[[") && strings.HasSuffix(miseStripComment(trimmed), "]") && !strings.Contains(trimmed, "=") {
142				section = strings.Join(miseHeader(strings.TrimSpace(miseStripComment(trimmed))), "|")
143				if file[section] == nil {
144					file[section] = map[string]string{}
145				}
146				continue
147			}
148			key, value, ok := strings.Cut(trimmed, "=")
149			if !ok {
150				continue
151			}
152			key = strings.Trim(strings.TrimSpace(key), `"'`)
153			value = strings.TrimSpace(value)
154			raw := value
155			switch {
156			case strings.HasPrefix(value, `"""`) || strings.HasPrefix(value, `'''`):
157				delim := value[:3]
158				for !strings.Contains(raw[3:], delim) && i+1 < len(lines) {
159					i++
160					raw += "\n" + lines[i]
161				}
162			default:
163				raw = strings.TrimSpace(miseStripComment(value))
164				depth := miseDepth(raw)
165				for depth > 0 && i+1 < len(lines) {
166					i++
167					more := miseStripComment(lines[i])
168					raw += "\n" + more
169					depth += miseDepth(more)
170				}
171			}
172			if file[section] == nil {
173				file[section] = map[string]string{}
174			}
175			file[section][key] = raw
176		}
177		return file
178	}
179	
180	// task returns the keys of a task, merging its sub-tables ([tasks."x".tools])
181	// under the name of the sub-table.
182	func (f miseFile) task(name string) (map[string]string, bool) {
183		base := "tasks|" + name
184		keys, found := f[base]
185		merged := map[string]string{}
186		for k, v := range keys {
187			merged[k] = v
188		}
189		for section, sub := range f {
190			if !strings.HasPrefix(section, base+"|") {
191				continue
192			}
193			var lines []string
194			for k, v := range sub {
195				lines = append(lines, k+" = "+v)
196			}
197			sort.Strings(lines)
198			merged[strings.TrimPrefix(section, base+"|")] = strings.Join(lines, "\n")
199			found = true
200		}
201		return merged, found
202	}
203	
204	var (
205		miseQuoted  = regexp.MustCompile(`"([^"]*)"|'([^']*)'`)
206		miseTaskRef = regexp.MustCompile(`task\s*=\s*["']([^"']+)["']`)
207	)
208	
209	// miseRefs lists the tasks a task depends on or runs: the strings of
210	// depends, depends_post and wait_for, and every `{ task = "x" }` of run.
211	func miseRefs(keys map[string]string) []string {
212		var refs []string
213		for _, k := range []string{"depends", "depends_post", "wait_for"} {
214			for _, m := range miseQuoted.FindAllStringSubmatch(keys[k], -1) {
215				refs = append(refs, m[1]+m[2])
216			}
217		}
218		for _, m := range miseTaskRef.FindAllStringSubmatch(keys["run"], -1) {
219			refs = append(refs, m[1])
220		}
221		return refs
222	}
