224	func TestMiseReaderUnderstandsTheFile(t *testing.T) {
225		// A reader that silently misses a table would make the guards below pass
226		// vacuously, so the file is checked against what it is known to contain.
227		f := loadMise(t)
228		for _, name := range []string{"build", "test", "test-race", "check", "ci", "lint"} {
229			if _, ok := f.task(name); !ok {
230				t.Errorf("task %q was not read from mise.toml", name)
231			}
232		}
233		if ci, _ := f.task("ci"); !strings.Contains(ci["run"], `"test-race"`) {
234			t.Errorf("the run array of ci was not read in full: %q", ci["run"])
235		}
236		if check, _ := f.task("check"); !strings.Contains(check["depends"], `"lint"`) {
237			t.Errorf("depends of check was not read: %q", check["depends"])
238		}
239		if _, ok := f["tools"]["go"]; !ok {
240			t.Error("the [tools] table was not read")
241		}
242	}
