244	func TestMiseReaderOnASample(t *testing.T) {
245		f := parseMise(`
246	[tools]
247	go = "1.27" # trailing comment
248	
249	[tasks."nexus-bench:up"]
250	description = "x # not a comment"
251	tools = { kubectl = "1.33" }
252	run = '''
253	go run ./a "quoted" up
254	'''
255	
256	[tasks."nexus-bench:test".env]
257	DEVDESK_NEXUS_BENCH = "1"
258	
259	[tasks.ci]
260	run = [
261	  # a comment
262	  { task = "fmt-check" },
263	  { task = "vet" },
264	]
265	`)
266		if f["tools"]["go"] != `"1.27"` {
267			t.Errorf("tools.go = %q", f["tools"]["go"])
268		}
269		up, ok := f.task("nexus-bench:up")
270		if !ok || !strings.Contains(up["tools"], "kubectl") || !strings.Contains(up["run"], "go run ./a") || up["description"] != `"x # not a comment"` {
271			t.Errorf("nexus-bench:up misread: %v", up)
272		}
273		test, _ := f.task("nexus-bench:test")
274		if !strings.Contains(test["env"], "DEVDESK_NEXUS_BENCH") {
275			t.Errorf("the env sub-table was not merged: %v", test)
276		}
277		ci, _ := f.task("ci")
278		if got := miseRefs(ci); strings.Join(got, ",") != "fmt-check,vet" {
279			t.Errorf("refs of ci = %v", got)
280		}
281	}
