283	func TestMiseDeclaresTheSixBenchTasks(t *testing.T) {
284		f := loadMise(t)
285		names := []string{}
286		for _, sub := range miseBenchSubcommands {
287			names = append(names, miseBenchPrefix+":"+sub)
288		}
289		names = append(names, miseBenchPrefix+":test")
290		for _, name := range names {
291			if _, ok := f.task(name); !ok {
292				t.Errorf("mise.toml has no task %q", name)
293			}
294		}
295	}
