297	func TestMiseBenchTasksCallTheCommand(t *testing.T) {
298		f := loadMise(t)
299		for _, sub := range miseBenchSubcommands {
300			name := miseBenchPrefix + ":" + sub
301			t.Run(name, func(t *testing.T) {
302				task, ok := f.task(name)
303				if !ok {
304					t.Fatalf("mise.toml has no task %q", name)
305				}
306				re := regexp.MustCompile(`go run \./internal/nexusbench/cmd/nexus-bench ` + sub + `(["'\s]|$)`)
307				if !re.MatchString(task["run"]) {
308					t.Errorf("run of %s does not call `go run ./internal/nexusbench/cmd/nexus-bench %s`:\n%s", name, sub, task["run"])
309				}
310				if strings.TrimSpace(task["description"]) == "" {
311					t.Errorf("%s has no description, so `mise tasks` lists it blank", name)
312				}
313			})
314		}
315	}
