317	func TestMiseBenchTestTaskRunsTheIntegrationTestsGuarded(t *testing.T) {
318		name := miseBenchPrefix + ":test"
319		task, ok := loadMise(t).task(name)
320		if !ok {
321			t.Fatalf("mise.toml has no task %q", name)
322		}
323		if !strings.Contains(task["run"], "go test -count=1 -run Integration ./internal/nexusbench/...") {
324			t.Errorf("run of %s must be `go test -count=1 -run Integration ./internal/nexusbench/...`:\n%s", name, task["run"])
325		}
326		// The guard variable is set either by `env DEVDESK_NEXUS_BENCH=1` in the
327		// command or by the env of the task.
328		if !strings.Contains(task["run"], "DEVDESK_NEXUS_BENCH=1") && !strings.Contains(task["env"], "DEVDESK_NEXUS_BENCH") {
329			t.Errorf("%s does not set DEVDESK_NEXUS_BENCH=1", name)
330		}
331	}
