333	// No bench task is part of, or reachable from, a task the standard checks run.
334	func TestMiseNoStandardTaskReachesTheBench(t *testing.T) {
335		f := loadMise(t)
336		for _, root := range []string{"ci", "check", "test", "test-race"} {
337			t.Run(root, func(t *testing.T) {
338				if _, ok := f.task(root); !ok {
339					t.Fatalf("mise.toml has no task %q", root)
340				}
341				seen := map[string]bool{}
342				queue := []string{root}
343				for len(queue) > 0 {
344					name := queue[0]
345					queue = queue[1:]
346					if seen[name] {
347						continue
348					}
349					seen[name] = true
350					if strings.HasPrefix(name, miseBenchPrefix) {
351						t.Errorf("%s reaches the bench task %s", root, name)
352						continue
353					}
354					keys, _ := f.task(name)
355					for k, v := range keys {
356						if strings.Contains(v, miseBenchPrefix) {
357							t.Errorf("task %s (reached from %s) mentions %q in %s", name, root, miseBenchPrefix, k)
358						}
359					}
360					queue = append(queue, miseRefs(keys)...)
361				}
362			})
363		}
364	}
