366	// kubectl is declared once, on the bench tasks, or once, globally. Declared
367	// globally it would be installed for every CI run; the tasks are the better
368	// place, so a global declaration next to complete task declarations is refused.
369	func TestMiseKubectlIsDeclaredOnTheBenchTasks(t *testing.T) {
370		f := loadMise(t)
371		names := []string{miseBenchPrefix + ":test"}
372		for _, sub := range miseBenchSubcommands {
373			names = append(names, miseBenchPrefix+":"+sub)
374		}
375		var with, without []string
376		for _, name := range names {
377			task, ok := f.task(name)
378			if !ok {
379				t.Errorf("mise.toml has no task %q", name)
380				continue
381			}
382			if strings.Contains(task["tools"], "kubectl") {
383				with = append(with, name)
384			} else {
385				without = append(without, name)
386			}
387		}
388		_, globally := f["tools"]["kubectl"]
389		switch {
390		case len(with) == len(names) && globally:
391			t.Error("kubectl is declared in the global [tools] and on every bench task: keep the tasks, drop the global one (it would be installed for every CI run)")
392		case len(with) == 0 && !globally:
393			t.Error("kubectl is declared nowhere: add it to the `tools` of each nexus-bench:* task (or to [tools])")
394		case len(with) > 0 && len(without) > 0:
395			t.Errorf("kubectl is declared on %v but not on %v: declare it on all six or on none", with, without)
396		}
397	}
