3	// Tests of the nexus-bench command (DEVDESK-504, step 8), written before the
4	// command. They pin down the contract of
5	//
6	//	func run(ctx context.Context, args []string, getenv func(string) string,
7	//		stdout, stderr io.Writer, d deps) int
8	//
9	// and of the `deps` struct, which carries every constructor and every library
10	// call that reaches a cluster, so that no test needs kubectl, a cluster or the
11	// network. The exact shape of `deps` these tests build is:
12	//
13	//	type deps struct {
14	//		newRunner  func(kubeContext string) (nexusbench.Runner, error)
15	//		newProber  func() nexusbench.Prober
16	//		clock      nexusbench.Clock
17	//		newStore   func(path string) (nexusbench.SecretStore, error)
18	//		newInitial func(r nexusbench.Runner, namespace string) nexusbench.InitialPassword
19	//		preflight  func(ctx context.Context, r nexusbench.Runner, p nexusbench.Params, op nexusbench.Op) (nexusbench.PreflightResult, error)
20	//		deploy     func(ctx context.Context, r nexusbench.Runner, pr nexusbench.Prober, clk nexusbench.Clock, p nexusbench.Params, out io.Writer) (nexusbench.DeployResult, error)
21	//		provision  func(ctx context.Context, baseURL string, ip nexusbench.InitialPassword, store nexusbench.SecretStore, p nexusbench.Params, out io.Writer) (nexusbench.ProvisionResult, error)
22	//		destroy    func(ctx context.Context, r nexusbench.Runner, clk nexusbench.Clock, store nexusbench.SecretStore, p nexusbench.Params, out io.Writer) error
23	//	}
24	//
