62	// fakeRunner records every kubectl call and answers the pod list; it fails the
63	// test on any write verb or any stdin, so a read-only command cannot cheat.
64	type fakeRunner struct {
65		t    *testing.T
66		mu   sync.Mutex
67		args [][]string
68		pods string
69	}
70	
71	var _ nexusbench.Runner = (*fakeRunner)(nil)
72	
73	var writeVerbs = map[string]bool{
74		"apply": true, "create": true, "delete": true, "patch": true, "replace": true,
75		"label": true, "annotate": true, "scale": true, "edit": true, "exec": true,
76		"cp": true, "drain": true, "cordon": true, "uncordon": true, "taint": true,
77		"rollout": true, "set": true, "run": true, "expose": true, "port-forward": true,
78	}
