80	func (r *fakeRunner) Run(_ context.Context, stdin []byte, args ...string) ([]byte, []byte, error) {
81		r.mu.Lock()
82		defer r.mu.Unlock()
83		r.args = append(r.args, append([]string(nil), args...))
84		r.t.Helper()
85		if len(stdin) > 0 {
86			r.t.Errorf("the runner was given stdin (%d bytes) by a command that must only read: kubectl %v", len(stdin), args)
87		}
88		for _, a := range args {
89			if writeVerbs[a] {
90				r.t.Errorf("the runner was asked to write (%q): kubectl %v", a, args)
91			}
92		}
93		for _, a := range args {
94			if a == "pods" || a == "pod" || strings.HasPrefix(a, "pods/") || strings.HasPrefix(a, "pod/") {
95				return []byte(r.pods), nil, nil
96			}
97		}
98		return nil, nil, nil
99	}
