159	
160		runner  *fakeRunner
161		prober  *fakeProber
162		clock   *fakeClock
163		store   *fakeStore
164		initial *fakeInitial
165	
166		mu     sync.Mutex
167		events []string
168	
169		// recorded
170		newRunnerContexts   []string
171		newStorePaths       []string
172		newInitialRunner    nexusbench.Runner
173		newInitialNamespace string
174		preflightOps        []nexusbench.Op
175		preflightParams     []nexusbench.Params
176		preflightRunner     nexusbench.Runner
177		deployParams        nexusbench.Params
178		deployRunner        nexusbench.Runner
179		deployProber        nexusbench.Prober
180		deployClock         nexusbench.Clock
181		provisionParams     nexusbench.Params
182		provisionURL        string
183		provisionInitial    nexusbench.InitialPassword
184		provisionStore      nexusbench.SecretStore
185		destroyParams       nexusbench.Params
186		destroyRunner       nexusbench.Runner
187		destroyClock        nexusbench.Clock
188		destroyStore        nexusbench.SecretStore
189		// descriptorSeenAtProvision is whether the descriptor file existed when the
190		// fake Provision ran: it must not have been written yet.
191		descriptorSeenAtProvision bool
192	
193		// programmable
194		newRunnerErr   error
195		newStoreErr    error
196		preflightRes   nexusbench.PreflightResult
197		preflightErr   error
198		deployRes      nexusbench.DeployResult
199		deployErr      error
200		provisionRes   nexusbench.ProvisionResult
201		provisionErr   error
