283	func (h *harness) deps() deps {
284		return deps{
285			newRunner: func(kubeContext string) (nexusbench.Runner, error) {
286				h.log("newRunner")
287				h.newRunnerContexts = append(h.newRunnerContexts, kubeContext)
288				if h.newRunnerErr != nil {
289					return nil, h.newRunnerErr
290				}
291				return h.runner, nil
292			},
293			newProber: func() nexusbench.Prober {
294				h.log("newProber")
295				return h.prober
296			},
297			clock: h.clock,
298			newStore: func(path string) (nexusbench.SecretStore, error) {
299				h.log("newStore")
300				h.newStorePaths = append(h.newStorePaths, path)
301				if h.newStoreErr != nil {
302					return nil, h.newStoreErr
303				}
304				return h.store, nil
305			},
306			newInitial: func(r nexusbench.Runner, namespace string) nexusbench.InitialPassword {
307				h.log("newInitial")
308				h.newInitialRunner, h.newInitialNamespace = r, namespace
309				return h.initial
310			},
311			preflight: func(ctx context.Context, r nexusbench.Runner, p nexusbench.Params, op nexusbench.Op) (nexusbench.PreflightResult, error) {
312				h.log("preflight:" + opName(op))
313				h.preflightOps = append(h.preflightOps, op)
314				h.preflightParams = append(h.preflightParams, p)
315				h.preflightRunner = r
316				if h.respectContext && ctx.Err() != nil {
317					return nexusbench.PreflightResult{}, ctx.Err()
318				}
319				return h.preflightRes, h.preflightErr
320			},
321			deploy: func(ctx context.Context, r nexusbench.Runner, pr nexusbench.Prober, clk nexusbench.Clock, p nexusbench.Params, out io.Writer) (nexusbench.DeployResult, error) {
322				h.log("deploy")
323				h.deployParams, h.deployRunner, h.deployProber, h.deployClock = p, r, pr, clk
324				_, _ = fmt.Fprintln(out, progressMarker+" deploy")
325				if h.onDeploy != nil {
326					h.onDeploy()
327				}
328				if h.respectContext && ctx.Err() != nil {
329					return nexusbench.DeployResult{}, fmt.Errorf("wait for Nexus: %w", ctx.Err())
330				}
331				return h.deployRes, h.deployErr
332			},
333			provision: func(ctx context.Context, baseURL string, ip nexusbench.InitialPassword, store nexusbench.SecretStore, p nexusbench.Params, out io.Writer) (nexusbench.ProvisionResult, error) {
334				h.log("provision")
335				h.provisionURL, h.provisionInitial, h.provisionStore, h.provisionParams = baseURL, ip, store, p
336				if _, err := os.Stat(h.descriptorPathOf(p)); err == nil {
337					h.descriptorSeenAtProvision = true
338				}
339				_, _ = fmt.Fprintln(out, progressMarker+" provision")
340				if h.respectContext && ctx.Err() != nil {
341					return nexusbench.ProvisionResult{}, fmt.Errorf("provision: %w", ctx.Err())
342				}
343				return h.provisionRes, h.provisionErr
344			},
345			destroy: func(ctx context.Context, r nexusbench.Runner, clk nexusbench.Clock, store nexusbench.SecretStore, p nexusbench.Params, out io.Writer) error {
346				h.log("destroy")
347				h.destroyRunner, h.destroyClock, h.destroyStore, h.destroyParams = r, clk, store, p
348				_, _ = fmt.Fprintln(out, progressMarker+" destroy")
349				if h.respectContext && ctx.Err() != nil {
350					return fmt.Errorf("delete: %w", ctx.Err())
351				}
352				return h.destroyErr
353			},
354		}
355	}
