403	// requireNoCalls fails when any dependency was used.
404	func (h *harness) requireNoCalls() {
405		h.t.Helper()
406		if ev := h.eventList(); len(ev) != 0 {
407			h.t.Errorf("no dependency should have been used, got %v", ev)
408		}
409		if calls := h.runner.calls(); len(calls) != 0 {
410			h.t.Errorf("the runner should not have been used, got %v", calls)
411		}
412	}
