414	// requireClean fails when an output carries a secret, a stack trace or the raw
415	// dump of a Go value (%+v, %#v).
416	func requireClean(t *testing.T, outputs ...string) {
417		t.Helper()
418		banned := []string{
419			secretMarker, REDACTED, "adminPassword", "pullPassword",
420			"goroutine ", "runtime/", "panic:", ".go:", "&{", "{Kind:", "Err:", "&nexusbench.", "nexusbench.BenchError", "%!",
421		}
422		for _, o := range outputs {
423			for _, b := range banned {
424				if strings.Contains(o, b) {
425					t.Errorf("output carries %q:\n%s", b, o)
426				}
427			}
428		}
429	}
