910		}
911	
912		// Order: the runner and the store exist before the cluster is touched;
913		// Deploy runs its own preflight(OpUp), so a preflight of the command is
914		// allowed but only before Deploy, and only for OpUp.
915		deploy, provision := h.index("deploy"), h.index("provision")
916		if deploy < 0 || provision < 0 || deploy > provision {
917			t.Fatalf("want deploy then provision, got %v", h.eventList())
918		}
919		for _, e := range []string{"newRunner", "newStore"} {
920			if i := h.index(e); i < 0 || i > deploy {
921				t.Errorf("%s must happen before Deploy, events: %v", e, h.eventList())
922			}
923		}
924		for _, op := range h.preflightOps {
925			if op != nexusbench.OpUp {
926				t.Errorf("up ran a preflight for %s, want OpUp only", opName(op))
927			}
928		}
929		if i := h.index("preflight:OpUp"); i > deploy {
930			t.Errorf("the preflight must come before Deploy, events: %v", h.eventList())
931		}
932		if h.has("destroy") {
933			t.Errorf("up destroyed something: %v", h.eventList())
934		}
935	
936		// What each step was given.
937		if h.deployRunner != nexusbench.Runner(h.runner) || h.deployProber != nexusbench.Prober(h.prober) || h.deployClock != nexusbench.Clock(h.clock) {
938			t.Error("Deploy was not given the runner, the prober and the clock of the deps")
939		}
940		if h.newInitialRunner != nexusbench.Runner(h.runner) || h.newInitialNamespace != "nexus-bench" {
941			t.Errorf("newInitial got (%v, %q), want the runner and the namespace", h.newInitialRunner, h.newInitialNamespace)
942		}
943		if h.provisionInitial != nexusbench.InitialPassword(h.initial) || h.provisionStore != nexusbench.SecretStore(h.store) {
944			t.Error("Provision was not given the InitialPassword of newInitial and the store of newStore")
945		}
946		if want := nexusbench.RESTBaseURL("127.0.0.1", h.provisionParams); h.provisionURL != want || want != "http://127.0.0.1:30481" {
947			t.Errorf("Provision base URL = %q, want %q", h.provisionURL, want)
948		}
949		if !h.provisionParams.AcceptEULA {
950			t.Error("--accept-eula did not reach Provision")
951		}
952		if h.descriptorSeenAtProvision {
953			t.Error("the descriptor existed before Provision ran")
954		}
955	
956		// The descriptor: what the library writes for these inputs, nothing else.
957		p := nexusbench.Defaults()
958		got, err := os.ReadFile(h.descriptor)
959		if err != nil {
960			t.Fatalf("no descriptor written: %v", err)
961		}
962		if want := wantDescriptorBytes(t, p, h.deployRes, h.provisionRes); !bytes.Equal(got, want) {
963			t.Errorf("descriptor bytes differ from BuildDescriptor:\n got %s\nwant %s", got, want)
964		}
965	
966		// Output: the progress of the steps, the place of the descriptor, no warning.
967		if !strings.Contains(stdout, h.descriptor) {
