1033		}{
1034			{"up: provision fails", "up", func(h *harness) {
1035				h.provisionErr = be
1036				// Provision returns what it had gathered together with the error.
1037				h.provisionRes = nexusbench.ProvisionResult{NexusVersion: "3.98.1-01", Edition: "COMMUNITY"}
1038			}},
1039			{"provision: provision fails", "provision", func(h *harness) {
