1041				h.provisionRes = nexusbench.ProvisionResult{NexusVersion: "3.98.1-01", Edition: "COMMUNITY"}
1042			}},
1043			{"up: deploy fails", "up", func(h *harness) { h.deployErr = be }},
1044			{"provision: preflight fails", "provision", func(h *harness) { h.preflightErr = be }},
1045		}
1046		for _, st := range steps {
1047			for _, existing := range []bool{false, true} {
1048				name := st.name + " / no descriptor yet"
1049				if existing {
1050					name = st.name + " / a descriptor exists"
1051				}
1052				t.Run(name, func(t *testing.T) {
1053					h := newHarness(t)
1054					st.setup(h)
1055					var before []byte
1056					if existing {
1057						other := nexusbench.Defaults()
1058						other.ImageTag = "3.97.0"
1059						before = h.writeDescriptor(other, nexusbench.DeployResult{}, nexusbench.ProvisionResult{NexusVersion: "3.97.0-01"})
1060					}
1061					code, stdout, stderr := h.run(st.sub, "--accept-eula")
1062					if code != 1 {
1063						t.Errorf("exit code = %d, want 1", code)
1064					}
1065					if got := strings.TrimSpace(stderr); got != be.Error() {
1066						t.Errorf("stderr = %q, want exactly the BenchError text %q", got, be.Error())
1067					}
1068					requireClean(t, stdout, stderr)
1069					if existing {
1070						after, err := os.ReadFile(h.descriptor)
1071						if err != nil || !bytes.Equal(before, after) {
